{
  "ontology_name": "Core_Ontology",
  "version": "2.0",
  "language": "en",
  "source_type": "technical PDF",
  "source_title": "hypertherm_powermax30_air_service_manual_rev4_808850.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Provides noise suppression and spike protection and contains sections used by the inverter.",
        "category": "power electronics"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Converts the 375 VDC bus voltage to nominal 15 VDC and supplies power to the internal air compressor.",
        "category": "power electronics"
      },
      {
        "component_id": "comp_control_board",
        "name": "Control board",
        "description": "Its microprocessor monitors and regulates system operation and safety circuits.",
        "category": "control"
      },
      {
        "component_id": "comp_current_sensors",
        "name": "Current sensors",
        "description": "Two sensors located on the power board; the system monitors the current sensor to compare set-point and output current.",
        "category": "sensing"
      },
      {
        "component_id": "comp_power_supply",
        "name": "Flyback circuit power supply",
        "description": "A DC-to-DC converter on the power board supplied by the bus voltage.",
        "category": "power supply"
      },
      {
        "component_id": "comp_relay",
        "name": "Relay",
        "description": "The power board resistor and relay implement the soft start.",
        "category": "switching"
      },
      {
        "component_id": "comp_internal_air_compressor",
        "name": "Internal air compressor",
        "description": "Powered by 15 VDC supplied by the compressor-driver board.",
        "category": "air system"
      },
      {
        "component_id": "comp_pfc_boost_converter",
        "name": "PFC boost converter",
        "description": "Provides a 375 VDC bus voltage when input AC voltage is between 120 and 240 VAC.",
        "category": "power conversion"
      },
      {
        "component_id": "comp_inverter",
        "name": "Inverter",
        "description": "Operates as a pulse-width modulator-controlled bridge circuit and is rectified by the output diode.",
        "category": "power electronics"
      },
      {
        "component_id": "comp_output_circuitry",
        "name": "Output circuitry",
        "description": "Consists of two current sensors, the pilot arc IGBT, and the output choke.",
        "category": "power electronics"
      }
    ],
    "Symptom": [],
    "FailureMode": [],
    "CorrectiveAction": [],
    "ErrorCode": []
  },
  "relations": []
}
